const initial=()=>({version:1,settings:{targetDate:'',commute:40,lesson:1,weekendExtra:20,bedtime:'23:00',workMode:'auto'},days:{},sleeps:[],weights:[],errors:[],mocks:[],reviews:[],pendingSleep:null});
