function day(k=selected){if(!state.days[k])state.days[k]={tasks:[],removed:[],sessions:[],study:[],notes:'',generated:false,mode:null};return state.days[k]}
function workday(k=selected){const mode=day(k).mode||state.settings.workMode;return mode==='work'||(mode==='auto'&&!weekend(k))}
