const topics=[['A useful skill you learned','描述你学过的一项实用技能：是什么、如何学、何时使用，以及为什么有用。'],['A place where you feel relaxed','描述一个让你放松的地方：在哪里、什么时候去、在那里做什么，以及为什么喜欢。'],['A person who encouraged you','描述一个鼓励过你的人：是谁、发生了什么、说了什么，以及你有什么感受。'],['A memorable meal','描述一次难忘的用餐：和谁、在哪里、吃了什么，以及为什么难忘。'],['A small goal you achieved','描述一个实现的小目标：目标是什么、做了什么、遇到什么困难，以及你的感受。'],['A book you enjoyed','描述一本你喜欢的书：书名、内容、何时读到，以及喜欢的原因。'],['Something you use every day','描述一件每天使用的物品：是什么、如何获得、如何使用，以及为什么有用。'],['A time you helped someone','描述一次帮助他人的经历：帮助了谁、做了什么，以及你有什么感受。'],['An activity you do at home','描述一项居家活动：做什么、多久做一次，以及为什么喜欢。'],['A journey you would like to take','描述一次想进行的旅行：去哪里、和谁去、想做什么，以及原因。'],['A piece of good news','描述一条好消息：是什么、何时得知、告诉了谁，以及你的感受。'],['A healthy habit','描述一个健康习惯：是什么、何时开始、如何坚持，以及给你带来什么变化。'],['A conversation you remember','描述一次记忆深刻的交谈：和谁、何时、聊了什么，以及为什么记得。'],['A change in your routine','描述一次日常安排的改变：改变了什么、为什么、怎样适应，以及你的感受。']];
function indexDay(k=selected){return Math.floor(Date.UTC(...k.split('-').map((n,i)=>Number(n)-(i===1?1:0)))/864e5)}
