if(sc.evening<10&&sc.isWork){for(const t of generated.filter(t=>t.cat==='健身')){t.title=t.id==='fit-main'?'可选：坐姿轻柔舒展':t.title;t.duration=t.id==='fit-main'?3:1;t.detail='今天已经很辛苦，休息优先；感到疲劳就跳过。';t.slot='睡前（可选）'}}
