function sleepCard(){const s=sleepFor(),h=s?sleepHours(s):0,pending=state.pendingSleep,avg=weekSleep();return `<section class="card"><div class="card-head"><div class="card-title"><span class="card-icon">☾</span><div><h3>让休息，成为开始</h3><small>SLEEP & REST</small></div></div><span class="badge">${s?h>=7?'睡眠已达7小时':'今天轻量一点':'目标 7–8 小时'}</span></div><div class="metrics-row"><div><div class="metric">${s?h.toFixed(1):'—'} <small>小时</small></div><div class="label">${pending?'正在记录本次睡眠':'最近一晚睡眠'}</div></div><div><strong style="font-size:15px;font-weight:400">${s?time(s.bed)+' → '+time(s.wake):'今晚，好好休息'}</strong><div class="label">近7天平均 ${avg.count?avg.avg.toFixed(1)+'h':'暂无记录'}</div></div></div><div class="button-row"><button class="primary" data-action="bed" ${pending?'disabled':''}>☾ 入睡打卡</button><button data-action="wake" ${!pending?'disabled':''}>☀ 起床打卡</button></div><div class="note">${pending?'已于 '+time(pending)+' 记录入睡，醒来后再打卡。':'稳定作息比熬夜补课更有意义。睡够，再慢慢来。'}</div><div class="mini-row"><button class="text-btn" data-action="sleep-edit">补记 / 修正时间</button><a style="margin-left:auto" href="#sleep">睡眠台账 ↗</a></div></section>`}
function workCard(){const d=day(),n=workMinutes(),active=d.sessions.find(s=>!s.end),sc=schedule();return `<section class="card"><div class="card-head"><div class="card-title"><span class="card-icon">◷</span><div><h3>工作有弹性，生活也一样</h3><small>FLEXIBLE WORKDAY</small></div></div><span class="badge ${n>=480?'':'sand'}">${sc.isWork?n>=480?'已满 8 小时':'累计 8 小时即可':'今天不上班'}</span></div><div class="metrics-row"><div><div class="metric" id="work-hours">${sc.isWork?(n/60).toFixed(1):'—'} <small>小时</small></div><div class="label">今日累计在岗 ${active?'· 计时中':''}</div></div><div><strong style="font-size:15px;font-weight:400">${sc.isWork?clock(sc.home):'自由安排'}</strong><div class="label">${sc.isWork?d.sessions.some(s=>s.end)?'预计到家时间':'按满8小时推算到家':'学习与运动可自主加时'}</div></div></div><div class="button-row"><button class="primary" data-action="work-in" ${!sc.isWork||active?'disabled':''}>↗ 上班打卡</button><button data-action="work-out" ${!active?'disabled':''}>↙ 下班打卡</button></div><div class="mini-row"><label>通勤 <input id="commute" type="number" min="0" max="300" value="${state.settings.commute}" aria-label="通勤分钟"> 分钟</label><strong>${sc.isWork?'还需 '+hm(Math.max(0,480-n)):'周末，不赶时间'}</strong></div><div class="mini-row"><button class="text-btn" data-action="work-edit">补记 / 修正班次</button><a style="margin-left:auto" href="#work">出勤台账 ↗</a></div></section>`}
