function importBackup(){const inp=document.createElement('input');inp.type='file';inp.accept='.json,application/json';inp.onchange=async()=>{try{if(inp.files[0].size>10e6)throw Error('文件过大，请选择10MB以内的备份');const d=validateBackup(JSON.parse(await inp.files[0].text()));pendingImport=d;modal('确认恢复这份备份？',`<p>备份包含 ${Object.keys(d.days).length} 天日记录、${d.sleeps.length} 条睡眠、${d.weights.length} 条体重和 ${d.errors.length} 条错题。</p><p class="notice">确认后会替换当前浏览器的数据。建议先导出当前备份，再恢复。</p><div class="button-row"><button data-action="export">先导出当前数据</button><button class="primary" data-action="restore-confirm">确认替换并恢复</button></div>`)}catch(e){toast('无法恢复：'+e.message)}};inp.click()}
const actions={add:addTask,close:()=>{$('#modal').close();stopTimer(false)},menu:()=>$('.sidebar').classList.toggle('open'),export:exportBackup,import:importBackup,settings,practice,study:addStudy,error:()=>addError(),lesson:()=>modal('按掌握情况调整课次',`<p class="note">默认从第一册第1课开始，不自动赶课。听懂、能跟读并替换造句后，再进入下一课。</p>${field('新概念第一册课次',input('lesson',state.settings.lesson,'number','min="1" max="144" required'))}`,'保存当前课次','lesson-form'),'next-lesson':()=>{if(state.settings.lesson>=144)return toast('第一册已到最后一课，先完成整体复习');modal('准备好进入下一课了吗？',`<p>确认第${state.settings.lesson}课已能听懂、跟读，并能用当课句型说两句话。</p><div class="button-row"><button data-action="close">再巩固一次</button><button class="primary" data-action="lesson-confirm">已掌握，进入下一课</button></div>`)},'lesson-confirm':()=>{state.settings.lesson++;ensure();render();$('#modal').close();toast('下一课已经准备好，继续按自己的节奏')},'restore-confirm':()=>{if(!pendingImport)return;state={...initial(),...pendingImport,settings:{...initial().settings,...pendingImport.settings}};pendingImport=null;ensure();render();$('#modal').close();toast('备份恢复完成')},'sleep-edit':()=>editSleep(),'work-edit':()=>editWork(),bed:()=>{if(selected!==dateKey())return editSleep();state.pendingSleep=new Date().toISOString();const t=day().tasks.find(t=>t.id==='sleep-bed');if(t)t.done=true;save();render();toast('晚安，Lyra。放下任务，好好睡觉。')},wake:()=>{if(!state.pendingSleep)return;const wake=new Date().toISOString(),h=(new Date(wake)-new Date(state.pendingSleep))/36e5;if(h<=0||h>24)return toast('睡眠时间需要修正，请使用补记功能');const k=dateKey();state.sleeps=state.sleeps.filter(s=>s.date!==k);state.sleeps.push({date:k,bed:state.pendingSleep,wake});state.pendingSleep=null;selected=k;ensure();render();toast('早安，今天的计划已按起床时间调整')},'work-in':()=>{if(selected!==dateKey())return editWork();if(Object.values(state.days).some(d=>d.sessions.some(s=>!s.end)))return toast('还有一段在岗记录，请先在对应日期下班或修正');day().sessions.push({start:new Date().toISOString(),end:null});const out=day().tasks.find(t=>t.id==='work-out');if(out)out.done=false;ensure();render();toast('上班已记录，按你的弹性节奏来')},'work-out':()=>{const s=day().sessions.find(s=>!s.end);if(!s)return;s.end=new Date().toISOString();ensure();render();toast('下班辛苦了，到家后计划已调整')},weights:()=>modal('体重记录',`<div class="table-wrap"><table><thead><tr><th>日期</th><th>体重 / 斤</th><th></th></tr></thead><tbody>${[...state.weights].sort((a,b)=>b.date.localeCompare(a.date)).map(w=>`<tr><td>${w.date}</td><td>${w.value}</td><td><button class="text-btn" data-weightdel="${w.date}">删除</button></td></tr>`).join('')||'<tr><td colspan="3">暂无记录</td></tr>'}</tbody></table></div>`),mock:()=>modal('记录一次模考',`<div class="form-grid">${field('模考日期',input('date',selected,'date','required'),true)}${['听力','阅读','写作','口语'].map((s,i)=>field(s,input('score'+i,5,'number','min="0" max="9" step="0.5" required'))).join('')}${field('备注',input('note','','text','maxlength="400"'),true)}</div>`,'保存模考','mock-form'),'timer-start':()=>{if(timer)return;timer={start:Date.now(),date:selected};$('[data-action="timer-start"]').disabled=true;$('[data-action="timer-finish"]').disabled=false;$('#timer-status').textContent='开始说吧。不暂停，不用重来。';timer.interval=setInterval(()=>{const remaining=Math.max(0,120-Math.floor((Date.now()-timer.start)/1000));if($('#timer-value'))$('#timer-value').textContent=`${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`;if(remaining===0){stopTimer(true);$('#timer-status').textContent='2分钟已完成并记录。接下来只选3处问题复盘。';$('[data-action="timer-finish"]').disabled=true;render()}},250)},'timer-finish':()=>{stopTimer(true);$('#modal').close();render()}};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b){actions[b.dataset.action]?.();return}const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;render();return}const del=e.target.closest('[data-delete]');if(del){const d=day(),t=d.tasks.find(t=>t.id===del.dataset.delete);if(!t)return;d.tasks=d.tasks.filter(x=>x.id!==t.id);if(t.generated)d.removed.push(t.id);save();render();toast('已移除任务，不会在今天自动加回来');return}const detail=e.target.closest('[data-detail]');if(detail){const t=day().tasks.find(t=>t.id===detail.dataset.detail);modal('任务小卡',`<h3>${esc(t.title)}</h3><p class="note">${esc(t.detail||'按你的节奏完成就好。')}</p><div class="pill-list"><span class="badge">${esc(t.cat)}</span><span class="badge">${esc(t.slot)}</span><span class="badge">${t.duration||0} 分钟</span></div>${t.cat==='新概念'||t.cat==='雅思'?'<div class="button-row"><button class="primary" data-action="study">记录有效学习时间</button></div>':''}`);return}
for(const [attr,fn] of [['sleepedit',editSleep],['workedit',editWork],['erredit',addError],['resolve',id=>{const e=state.errors.find(x=>x.id===id);e.resolved=!e.resolved;save();render()}],['errdel',id=>{state.errors=state.errors.filter(x=>x.id!==id);save();render()}],['mockdel',id=>{state.mocks=state.mocks.filter(x=>x.id!==id);save();render()}],['studydel',val=>{const [k,id]=val.split('|');day(k).study=day(k).study.filter(x=>x.id!==id);save();render()}],['weightdel',date=>{state.weights=state.weights.filter(x=>x.date!==date);save();render();actions.weights()}]]){const el=e.target.closest('[data-'+attr+']');if(el){fn(el.dataset[attr]);return}}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.task){const t=day().tasks.find(t=>t.id===el.dataset.task);t.done=el.checked;save();render();return}if(el.id==='viewdate'){if(!el.value||el.value>dateKey())return;selected=el.value;ensure();render()}if(el.id==='target-date'){state.settings.targetDate=el.value;save();render()}if(el.id==='commute'){const n=Number(el.value);if(n<0||n>300||!Number.isFinite(n)){toast('通勤请输入0–300分钟');return render()}state.settings.commute=n;ensure();render()}if(el.id==='day-mode'){day().mode=el.value;ensure();render()}if(el.id==='fitness-note'){day().notes=el.value;save()}if(el.id==='nce-note'){day().nceNote=el.value;save()}if(el.id==='weekly-note'){state.reviews=state.reviews.filter(r=>r.date!==selected);state.reviews.push({date:selected,text:el.value});save()}});
document.addEventListener('input',e=>{if(['fitness-note','nce-note','weekly-note'].includes(e.target.id))e.target.dispatchEvent(new Event('change',{bubbles:true}))});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,v=Object.fromEntries(new FormData(f));try{if(f.id==='add-form'){const title=v.title.trim();if(!title)throw Error('请填写任务内容');day().tasks.push({id:uid(),title,cat:v.cat,duration:Number(v.duration),slot:v.slot,detail:v.detail,done:false,generated:false})}else if(f.id==='sleep-form'){const bed=new Date(v.bed),wake=new Date(v.wake),hours=(wake-bed)/36e5;if(!Number.isFinite(hours)||hours<=0||hours>24)throw Error('起床需晚于入睡，睡眠应在0–24小时内');if(wake>new Date())throw Error('不能记录未来的起床时间');const k=dateKey(wake);if(state.sleeps.some(s=>s.date!==v.key&&s.date!==k&&new Date(s.bed)<wake&&new Date(s.wake)>bed))throw Error('与另一晚睡眠重叠，请检查时间');state.sleeps=state.sleeps.filter(s=>s.date!==k&&s.date!==v.key);state.sleeps.push({date:k,bed:bed.toISOString(),wake:wake.toISOString()});state.pendingSleep=null;selected=k;generate(v.key)}else if(f.id==='work-form'){const sessions=[];for(let i=0;i<Number(v.count);i++){const a=v['start'+i],b=v['end'+i];if(!a&&!b)continue;if(!a)throw Error('每段班次都需填写上班时间');if(dateKey(new Date(a))!==v.key)throw Error('班次开始日期需为 '+v.key);if(new Date(a)>new Date()||(b&&new Date(b)>new Date()))throw Error('不能记录未来的打卡时间');if(b&&(new Date(b)<=new Date(a)||(new Date(b)-new Date(a))/36e5>24))throw Error('下班应晚于上班，单段不超过24小时');sessions.push({start:new Date(a).toISOString(),end:b?new Date(b).toISOString():null})}sessions.sort((a,b)=>a.start.localeCompare(b.start));if(sessions.filter(s=>!s.end).length>1)throw Error('最多保留一个在岗班次');for(let i=1;i<sessions.length;i++)if(!sessions[i-1].end||sessions[i].start<sessions[i-1].end)throw Error('班次时间不能重叠');const others=Object.entries(state.days).filter(([k])=>k!==v.key).flatMap(([k,d])=>d.sessions);if(sessions.some(s=>others.some(o=>new Date(s.start)<new Date(o.end||new Date())&&new Date(s.end||new Date())>new Date(o.start))))throw Error('与其他日期的班次重叠');day(v.key).sessions=sessions;selected=v.key}else if(f.id==='study-form'){day().study.push({id:uid(),cat:v.cat,skill:v.cat==='雅思'?v.skill:'基础输入',minutes:Number(v.minutes),note:v.note})}else if(f.id==='error-form'){const old=state.errors.find(x=>x.id===v.id);const entry={id:old?.id||uid(),date:old?.date||selected,type:v.type,original:v.original,correct:v.correct,reason:v.reason,resolved:old?.resolved||false};state.errors=state.errors.filter(x=>x.id!==entry.id);state.errors.push(entry)}else if(f.id==='settings-form'){Object.assign(state.settings,{targetDate:v.targetDate,commute:Number(v.commute),bedtime:v.bedtime,weekendExtra:Number(v.weekendExtra)})}else if(f.id==='lesson-form'){state.settings.lesson=Number(v.lesson)}else if(f.id==='mock-form'){state.mocks.push({id:uid(),date:v.date,scores:[0,1,2,3].map(i=>Number(v['score'+i])),note:v.note})}else if(f.id==='weight-form'){const n=Number(v.weight);if(n<40||n>500)throw Error('请检查体重单位：斤');state.weights=state.weights.filter(w=>w.date!==selected);state.weights.push({date:selected,value:n});save();render();return toast('今日体重已记录')}else return;ensure();render();$('#modal').close();toast('已保存，今天按自己的节奏来')}catch(err){const target=$('#formerror');if(target)target.textContent=err.message;else toast(err.message)}});
